def fact(n):
    if n == 0:
        return 1
    return n*fact(n-1)
print(fact(5))

def appels(n):
    if n == 0:
        return 1
    return 1 + appels(n-1)
print(appels(3))

def puissance(n, p):
    if p == 0:
        return 1
    return n*puissance(n, p-1)
print(puissance(3, 4))

def palindrome(s):
    if len(s) <= 1:
        return True
    return s[0] == s[-1] and palindrome(s[1:-1])
print(palindrome("radar"), palindrome("rame"))

def aplatir(blocs):
    if not blocs:
        return []
    return blocs[0] + aplatir(blocs[1:])
print(aplatir([[1], [2, 3], []]))

def fib(n, memo):
    if n not in memo:
        memo[n] = fib(n-1, memo) + fib(n-2, memo)
    return memo[n]
print(fib(6, {1: 1, 2: 1}))

