class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def distance(self, autre):
        return ((self.x-autre.x)**2 + (self.y-autre.y)**2)**0.5
print(Point(1, 2).distance(Point(4, 6)))

class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __str__(self):
        return f"<{self.x};{self.y}>"
print(Point(2, 5))

class Fraction:
    def __init__(self, n, d):
        self.n, self.d = n, d
    def __add__(self, autre):
        return Fraction(self.n*autre.d + autre.n*self.d, self.d*autre.d)
    def __str__(self):
        return f"{self.n}/{self.d}"
print(Fraction(1, 2) + Fraction(1, 5))

